pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // The test contract deployed c in setUp, so it is the current owner
        // (constructor set owner = msg.sender = address(this)).
        vm.prank(address(this));
        bool ok = c.setOwner(newOwner);

        // General rule: after a successful owner call, owner() equals the
        // requested address, and setOwner reports success.
        assertTrue(ok && c.owner() == newOwner);
    }
}

