import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (caller != c.owner()) {
            assertTrue(!ok && c.owner() != newOwner);
        } else {
            assertTrue(ok ? c.owner() == newOwner : true);
        }
    }
}

