pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // General rule: a non-owner can never change ownership; ownership only
        // changes when the current owner calls setOwner. The buggy contract
        // lets any non-owner succeed (ok == true) and blocks the owner.
        assertTrue(!ok, "non-owner must not be able to set the owner");
    }
}

