pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // current owner is the deployer (this contract); only owner may call
        vm.assume(caller == address(this));
        (bool ok, bytes memory ret) =
            address(c).call(abi.encodeWithSelector(C.setOwner.selector, newOwner));
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (bool)) == true);
    }
}

